import { test, expect } from "@playwright/test";
import { mkdir } from "node:fs/promises";
// The SSR bundle describes the exact build under test (production or preview).
// @ts-ignore — generated by the build
import { routes, entries } from "../../.prerender/render.js";

test("all pages at 1440px and 390px", async ({ page }) => {
  test.setTimeout(180000);
  // A full-page screenshot stretches the fixed WebGL canvas beyond normal
  // viewport/texture limits on the long index. Capture the static Bayer layout;
  // separate tests exercise the live canvas at real viewport sizes.
  await page.emulateMedia({ reducedMotion: "reduce" });
  await mkdir("test-results/screenshots", { recursive: true });
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: width === 390 ? 844 : 900 });
    for (const route of routes) {
      const errors: string[] = [];
      const onError = (error: Error) => errors.push(error.message);
      page.on("pageerror", onError);
      await page.goto(route + "?noloader");
      await expect(page.locator("h1")).toBeVisible();
      await page.evaluate(() => {
        document
          .querySelectorAll("img")
          .forEach((img) => (img.loading = "eager"));
        return document.fonts.ready;
      });
      await expect
        .poll(() =>
          page
            .locator("img")
            .evaluateAll(
              (imgs) =>
                imgs.filter((img) => !(img as HTMLImageElement).complete)
                  .length,
            ),
        )
        .toBe(0);
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBeTruthy();
      expect(errors, route).toEqual([]);
      await page.screenshot({
        path: `test-results/screenshots/${route === "/" ? "home" : route.replaceAll("/", "_")}-${width}.png`,
        fullPage: true,
      });
      page.off("pageerror", onError);
    }
  }
});

test("loader FLIP handoff and repeat-visit resolve", async ({ browser }) => {
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    recordVideo: {
      dir: "test-results/handoff",
      size: { width: 1440, height: 900 },
    },
  });
  const page = await context.newPage();
  await page.goto("http://127.0.0.1:4173/");
  await expect(page.locator("#pcl")).toBeVisible();
  await expect(page.locator("html")).toHaveAttribute(
    "data-media-renderer",
    "webgl2",
  );
  await expect(page.locator("#pcl.pcl-flight")).toBeAttached({ timeout: 8500 });
  await expect(page.locator("#pcl")).toHaveCount(0, { timeout: 10000 });
  const video = page.locator("[data-hero-video]");
  await expect
    .poll(() =>
      video.evaluate((v: HTMLVideoElement) => !v.paused && v.currentTime > 0.1),
    )
    .toBeTruthy();
  await expect(page.locator(".dither-overlay")).toHaveCount(1);
  await page.reload();
  await expect(page.locator("#pcl")).toHaveCount(0);
  await expect
    .poll(() => video.evaluate((v: HTMLVideoElement) => !v.paused))
    .toBeTruthy();
  await context.close();
});

test("reduced motion has no autoplay, no live canvas, and explicit clean playback", async ({
  browser,
}) => {
  const context = await browser.newContext({ reducedMotion: "reduce" });
  const page = await context.newPage();
  const requests: string[] = [];
  page.on("request", (r) => requests.push(r.url()));
  await page.goto("http://127.0.0.1:4173/?noloader");
  await expect(
    page.getByRole("button", { name: "Play film", exact: true }),
  ).toBeVisible();
  expect(requests.filter((r) => r.includes(".mp4"))).toEqual([]);
  await expect(page.locator(".dither-overlay")).toHaveCount(0);
  await page.getByRole("button", { name: "Play film", exact: true }).click();
  await expect(page.locator("[data-hero-video]")).toHaveAttribute(
    "controls",
    "",
  );
  await expect
    .poll(() =>
      page
        .locator("[data-hero-video]")
        .evaluate((v: HTMLVideoElement) => !v.paused),
    )
    .toBeTruthy();
  await context.close();
});

test("mobile navigation opens, closes with Escape, and restores focus", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/work/?noloader");
  const menu = page.locator("[data-menu-toggle]");
  await menu.click();
  await expect(menu).toHaveAttribute("aria-expanded", "true");
  await page.keyboard.press("Escape");
  await expect(menu).toHaveAttribute("aria-expanded", "false");
  await expect(menu).toBeFocused();
});

test("Ozzy has no YouTube request before click and uses the privacy iframe afterward", async ({
  page,
}) => {
  const requests: string[] = [];
  page.on("request", (r) => requests.push(r.url()));
  await page.route("https://www.youtube-nocookie.com/**", (route) =>
    route.fulfill({
      body: "<html><body>Video provider test response</body></html>",
      contentType: "text/html",
    }),
  );
  await page.goto("/work/ozzy/?noloader");
  expect(requests.filter((url) => /youtube|ytimg/.test(url))).toEqual([]);
  await expect(page.locator("iframe")).toHaveCount(0);
  await page.getByRole("button", { name: "Play full video" }).click();
  await expect(page.locator("iframe")).toHaveAttribute(
    "src",
    /youtube-nocookie\.com\/embed\/aOJ1GtodHKo/,
  );
  await expect(page.locator("[data-youtube] [data-dither]")).toHaveCount(0);
});

test("full films stay clean and the point cloud downloads only after activation", async ({
  page,
}) => {
  // Allow software CI GPUs extra time for the full million-point capture.
  // Keep the real asset and input path; also require disposal and focus recovery.
  test.setTimeout(180000);
  const requests: string[] = [];
  page.on("request", (r) => requests.push(r.url()));
  await page.goto("/work/jordan/?noloader");
  await expect(page.locator("[data-project-video]")).toHaveAttribute(
    "controls",
    "",
  );
  await expect(page.locator("[data-project-video]")).not.toHaveAttribute(
    "autoplay",
  );
  // Exercise the full, unchanged capture on a touch-sized viewport as well.
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/about/?noloader");
  expect(requests.filter((url) => /ksplat|splat-engine/.test(url))).toEqual([]);
  await page.getByRole("button", { name: "Explore the point cloud" }).click();
  await expect
    .poll(() => requests.some((url) => url.includes("converted_file.ksplat")))
    .toBeTruthy();
  await expect(page.locator("[data-splat-status]")).toContainText(
    "Scene ready",
    { timeout: 60000 },
  );
  await page.getByRole("button", { name: "Close scene" }).click();
  await expect(
    page.getByRole("button", { name: "Explore the point cloud" }),
  ).toBeFocused();
  await expect(page.locator("[data-splat-mount] canvas")).toHaveCount(0);
  await expect(page.locator("[data-splat-status]")).toContainText("Scene closed");
});

