test("supplied films play on desktop and mobile with the correct sound labels", async ({ page }) => {
  test.setTimeout(180000);
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: width === 390 ? 844 : 900 });
    for (const entry of entries.filter((entry: { media: { film?: { audio?: boolean } } }) => entry.media.film?.audio !== undefined)) {
      await page.goto(`/work/${entry.slug}/?noloader`);
      const player = page.locator("[data-project-video]");
      await expect(player).toHaveAccessibleName(`${entry.title}, ${entry.media.film.audio ? "film with sound" : "silent film"}`);
      await player.evaluate((video: HTMLVideoElement) => {
        // Test playback without sending sound to the test machine's speakers.
        video.muted = true;
        return video.play();
      });
      await expect.poll(() => player.evaluate((video: HTMLVideoElement) => video.currentTime)).toBeGreaterThan(0.1);
      const expected = width > 700 && entry.media.film.hd ? entry.media.film.hd : entry.media.film.src;
      expect(await player.evaluate((video: HTMLVideoElement) => new URL(video.currentSrc).pathname)).toBe(expected);
      await expect(page.locator("[data-video-error]")).toBeHidden();
    }
  }
});

test("new categories retain live dither and only load lightweight muted card loops", async ({ page }) => {
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: width === 390 ? 844 : 900 });
    const requested: string[] = [];
    const record = (request: { url(): string }) => requested.push(request.url());
    page.on("request", record);
    await page.goto("/work/?noloader");
    for (const category of ["particle", "point-cloud"]) {
      await page.locator(`.category-nav a[href='#${category}']`).click();
      const first = page.locator(`#${category} video`).first();
      await first.scrollIntoViewIfNeeded();
      await expect(first).toHaveAttribute("src", /\/loop\.mp4$/);
      await expect.poll(() => first.evaluate((video: HTMLVideoElement) => !video.paused && video.currentTime > 0.1 && video.muted)).toBeTruthy();
      await expect(page.locator("html")).toHaveAttribute("data-media-renderer", "webgl2");
      await expect(page.locator(".dither-overlay")).toHaveCount(1);
      await page.screenshot({ path: `test-results/screenshots/${category}-live-${width}.png` });
    }
    expect(requested.filter((url) => /\/film(?:-1080)?\.mp4/.test(url))).toEqual([]);
    page.off("request", record);
  }
});

test("one media canvas, offscreen loops pause, and motion pause control works", async ({
  page,
}) => {
  await page.goto("/?noloader");
  await expect(page.locator("[data-hero-video]")).toHaveAttribute(
    "src",
    /jordan.mp4/,
  );
  await page.getByRole("button", { name: "Pause motion" }).click();
  expect(
    await page
      .locator("[data-loop]")
      .evaluateAll((vs) => vs.every((v) => (v as HTMLVideoElement).paused)),
  ).toBeTruthy();
  await page.getByRole("button", { name: "Resume motion" }).click();
  await page.locator(".site-footer").scrollIntoViewIfNeeded();
  await expect
    .poll(() =>
      page
        .locator("[data-hero-video]")
        .evaluate((v: HTMLVideoElement) => v.paused),
    )
    .toBeTruthy();
  await expect(page.locator(".dither-overlay")).toHaveCount(1);
});
